<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$pdo=db(); $code=strtoupper(trim((string)($_POST['code']??$_GET['code']??''))); $error=null; $info=null; $class=null;
if($code!==''){
 if(!preg_match('/^[A-Z0-9]{4,32}$/',$code)) $error='کد کلاس معتبر نیست.';
 else{$q=$pdo->prepare('SELECT c.*,u.name AS teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id WHERE c.room_code=? LIMIT 1');$q->execute([$code]);$class=$q->fetch();if(!$class)$error='کلاسی با این کد پیدا نشد.';}
 if($class){if($class['expires_at']!==null&&strtotime((string)$class['expires_at'])<=time()){$pdo->prepare("UPDATE classes SET status='expired' WHERE id=? AND status IN ('scheduled','active')")->execute([(int)$class['id']]);$error='زمان ورود به این کلاس تمام شده است.';}elseif(!in_array($class['status'],['scheduled','active'],true))$error='این کلاس دیگر قابل ورود نیست.';elseif(!current_user()&&!empty($class['allow_guest'])){}elseif(!current_user())redirect('/login/signin.php?next='.rawurlencode('/join/?code='.$code));}}
if($class&&!$error&&$_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$user=current_user();if(!$user){if(!empty($class['allow_guest']))redirect('/room/?code='.rawurlencode($code));redirect('/login/signin.php?next='.rawurlencode('/join/?code='.$code));}if((int)$class['teacher_id']===(int)$user['id']||$user['role']==='admin'){$pdo->prepare("INSERT INTO class_participants(class_id,user_id,role,joined_at,left_at,created_at,updated_at) VALUES(?,?, 'teacher',NOW(),NULL,NOW(),NOW()) ON DUPLICATE KEY UPDATE role='teacher',joined_at=NOW(),left_at=NULL,updated_at=NOW()")->execute([(int)$class['id'],(int)$user['id']]);redirect('/room/?code='.rawurlencode($code));}$allowed=false;if((bool)$pdo->query("SHOW TABLES LIKE 'class_allowed_users'")->fetch()){$q=$pdo->prepare('SELECT 1 FROM class_allowed_users WHERE class_id=? AND user_id=? LIMIT 1');$q->execute([(int)$class['id'],(int)$user['id']]);$allowed=(bool)$q->fetchColumn();}if($allowed){$pdo->prepare("INSERT INTO class_participants(class_id,user_id,role,joined_at,left_at,created_at,updated_at) VALUES(?,?, 'student',NOW(),NULL,NOW(),NOW()) ON DUPLICATE KEY UPDATE role='student',joined_at=NOW(),left_at=NULL,updated_at=NOW()")->execute([(int)$class['id'],(int)$user['id']]);redirect('/room/?code='.rawurlencode($code));}$q=$pdo->prepare('SELECT status FROM class_join_requests WHERE class_id=? AND user_id=? LIMIT 1');$q->execute([(int)$class['id'],(int)$user['id']]);$request=$q->fetchColumn();if($request==='approved')redirect('/room/?code='.rawurlencode($code));if($request==='pending')$info='درخواست ورودت قبلاً ارسال شده و منتظر تأیید مدرس یا مدیر است.';else{$pdo->prepare("INSERT INTO class_join_requests(class_id,user_id,status,requested_at) VALUES(?,?,'pending',NOW()) ON DUPLICATE KEY UPDATE status='pending',requested_at=NOW(),decided_at=NULL,decided_by=NULL,reject_reason=NULL")->execute([(int)$class['id'],(int)$user['id']]);$info='درخواست ورود ارسال شد. بعد از تأیید مدرس یا مدیر می‌توانی وارد کلاس شوی.';}}catch(Throwable $e){$error='ارسال درخواست ورود انجام نشد. جدول درخواست‌ها را بررسی کنید.';}}
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ورود به کلاس | کاداد کلاس</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><style>:root{--t:#101828;--m:#667085;--p:#635bff;--b:#e4e7ec}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:Vazirmatn,Tahoma,sans-serif;color:var(--t);background:linear-gradient(145deg,#f8f9ff,#eef2ff);display:grid;place-items:center;padding:24px}.wrap{width:min(520px,100%)}.brand{display:flex;justify-content:center;gap:10px;align-items:center;text-decoration:none;color:var(--t);font-weight:900;font-size:22px;margin-bottom:22px}.logo{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,#766cff,#5148e8)}.card{background:#fff;border:1px solid var(--b);border-radius:25px;padding:34px;box-shadow:0 24px 70px rgba(16,24,40,.1)}h1{margin:0 0 8px;font-size:29px}.intro{color:var(--m);line-height:1.9;margin:0 0 22px}.error,.info{padding:12px 14px;border-radius:13px;margin-bottom:16px;font-size:13px;font-weight:700}.error{background:#fff1f2;color:#be123c}.info{background:#eff6ff;color:#1d4ed8}label{display:block;font-size:13px;font-weight:800;margin-bottom:7px}input{width:100%;height:54px;border:1px solid var(--b);border-radius:14px;padding:0 16px;font:inherit;text-transform:uppercase;letter-spacing:2px;margin-bottom:18px}button{width:100%;height:55px;border:0;border-radius:15px;background:linear-gradient(135deg,#6d63ff,#5148e8);color:#fff;font:800 16px Vazirmatn;cursor:pointer}.classbox{background:#f8f9ff;border:1px solid var(--b);border-radius:14px;padding:14px;margin-bottom:18px}.classbox b{font-size:16px}.classbox small{display:block;color:var(--m);margin-top:5px}.back{display:block;text-align:center;margin-top:18px;color:var(--m);text-decoration:none;font-size:13px}</style></head><body><div class="wrap"><a class="brand" href="/home"><span class="logo">ک</span><span>کاداد کلاس</span></a><main class="card"><h1>ورود به کلاس 🎓</h1><p class="intro">کد کلاس را وارد کن؛ بعد از پیدا شدن کلاس، ورود مستقیم یا درخواست دسترسی انجام می‌شود.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><?php if($info):?><div class="info">✓ <?=h($info)?></div><?php endif;?><?php if($class&&!$error&&!$info):?><div class="classbox"><b><?=h($class['title'])?></b><small>مدرس: <?=h($class['teacher_name'])?> · کد: <?=h($class['room_code'])?></small></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><label>کد کلاس</label><input name="code" value="<?=h($code)?>" minlength="4" maxlength="32" required autofocus><button><?= $class?'ادامه و ورود':'پیدا کردن کلاس' ?></button></form></main><a class="back" href="/panel">← بازگشت به پنل</a></div></body></html>
